import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"审批、接管与外部副作用","description":"Hearth 如何让发送、写入、删除和发布等真实世界动作可预览、可授权、可对账、可恢复。","frontmatter":{"title":"审批、接管与外部副作用","description":"Hearth 如何让发送、写入、删除和发布等真实世界动作可预览、可授权、可对账、可恢复。","outline":false},"headers":[],"relativePath":"design/effects.md","filePath":"design/effects.md","lastUpdated":1793863446000}'),s={name:"design/effects.md"};function o(i,t,n,p,l,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="审批、接管与外部副作用" tabindex="-1">审批、接管与外部副作用 <a class="header-anchor" href="#审批、接管与外部副作用" aria-label="Permalink to &quot;审批、接管与外部副作用&quot;">​</a></h1><p class="lead">Hearth 真正的风险不在生成文字，而在替用户发出邮件、修改文件、提交表单、删除内容、付款或发布。外部动作必须经过清楚的预览、授权、执行和回执，不能因为模型说“已经完成”就相信结果。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>用户要在动作发生前看到它到底会做什么：目标系统、目标对象、关键参数、可能影响、是否可逆、需要什么权限。审批绑定的是这一次真实动作，而不是一句模糊的“允许助手操作邮箱”；参数变化、范围扩大或授权过期时，必须重新确认。</p><p>每个外部动作都要有可核对的结果。系统在执行前留下待执行意图，执行后保存回执，包括时间、目标、结果和撤销方式。网络中断或服务返回不确定时先对账，不重复发送；确认失败后进入可查看、可修复、可重放的队列。</p><p>人工接管不是最后兜底，而是设计的一部分。用户可以暂停正在进行的任务，保留当前进度和已完成动作，直接接手操作，再把结果交回系统继续验证。接管过程中的关键动作和判断也要记录下来，成为后续改进的依据。</p><p>审批要按风险和可逆性分级。读取和整理通常只需有限授权；发送、发布、删除、付款和设备操作需要更强确认；不可逆或高金额动作即使已经预授权，也应有金额、对象或时间上的硬限制。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>外部动作采用“先预览、再授权、后执行、最后对账”的顺序。系统和执行器都不能绕过这条链路直接调用外部服务；连接器和桌面执行器只负责在授权范围内完成动作，不自行决定动作是否应该发生。</p><table tabindex="0"><thead><tr><th>动作类型</th><th>默认策略</th><th>例外</th></tr></thead><tbody><tr><td>读取、搜索、整理</td><td>可在任务范围内授权</td><td>涉及敏感数据时收窄范围并提示</td></tr><tr><td>创建草稿、生成文件</td><td>可直接执行，保留产物和版本</td><td>覆盖原文件前必须预览差异</td></tr><tr><td>发送消息、提交表单</td><td>每次确认目标、内容和范围</td><td>低风险重复动作可在明确范围内预授权</td></tr><tr><td>删除、发布、付款、设备操作</td><td>默认人工确认</td><td>不做无条件自动执行</td></tr><tr><td>无法保证可逆的动作</td><td>必须人工接管或明确承担风险</td><td>不通过“多试几次”绕过</td></tr></tbody></table><p>授权范围要能被普通用户理解。审批卡应该用自然语言说明“对谁、做什么、什么时候、做到什么程度”，同时保留可展开的技术细节供需要时核对。用户拒绝后，系统不能换个说法再次请求同一动作。</p><p>幂等和对账是外部动作的基础要求。一次发送只能产生一封邮件，一次提交只能产生一条记录；重试必须复用同一标识。外部系统没有返回明确结果时，系统进入“不确定”状态，先查询或让用户确认，而不是直接再执行一次。</p><p>人的错误也是输入。用户可能批准了错误内容、撤销了正确动作或给出了矛盾指令；系统要保留上下文，支持纠正、补偿和重新审批，不把人的操作当作不可质疑的真相。最终目标是让责任边界清楚，而不是让系统假装永远不会出错。</p>',13)])])}const f=e(s,[["render",o]]);export{_ as __pageData,f as default};
